package com.gameaggregator.billingservice.application;import com.gameaggregator.platform.core.common.exception.NotFoundException;import com.gameaggregator.billingservice.api.BillingDtos.*;import com.gameaggregator.billingservice.domain.*;import com.gameaggregator.billingservice.infrastructure.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service @Transactional public class BillingService{final BillingPlanRepository plans;final UsageRecordRepository usage;final InvoiceRepository invoices;final InvoiceItemRepository items;final CreditNoteRepository credits;public BillingService(BillingPlanRepository p,UsageRecordRepository u,InvoiceRepository i,InvoiceItemRepository x,CreditNoteRepository c){plans=p;usage=u;invoices=i;items=x;credits=c;}public BillingPlan plan(Plan r){return plans.save(new BillingPlan(r.code(),r.cycle(),r.usageQuota(),r.price(),r.currency()));}public UsageRecord usage(Usage r){return usage.save(new UsageRecord(r.idempotencyKey(),r.clientId(),r.quantity(),r.occurredAt()));}public Invoice invoice(InvoiceRequest r){if(r.cycleTo().isBefore(r.cycleFrom()))throw new IllegalArgumentException("Invalid billing cycle");return invoices.save(new Invoice(r.invoiceNumber(),r.clientId(),r.cycleFrom(),r.cycleTo(),r.total(),r.currency()));}public InvoiceItem item(UUID id,Item r){invoice(id);return items.save(new InvoiceItem(id,r.description(),r.quantity(),r.unitPrice()));}public CreditNote credit(UUID id,Credit r){var i=invoice(id);if(r.amount().compareTo(i.total)>0)throw new IllegalArgumentException("Credit exceeds invoice total");return credits.save(new CreditNote(id,r.amount(),r.reason()));}public Invoice payment(UUID id,Payment r){var i=invoice(id);i.paymentStatus=r.status();return i;}public Invoice invoice(UUID id){return invoices.findById(id).orElseThrow(()->new NotFoundException("INVOICE_NOT_FOUND","Invoice was not found"));}public List<Invoice> report(){return invoices.findAll();}}